"use strict";(globalThis.webpackChunktechnical_writing_portfolio=globalThis.webpackChunktechnical_writing_portfolio||[]).push([[3886],{7521(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>s,default:()=>p,frontMatter:()=>r,metadata:()=>o,toc:()=>c});const o=JSON.parse('{"id":"ably/sse-documentation","title":"Server-sent events documentation","description":"When I started working on the Server-Sent Events documentation at Ably, I quickly realized this wasn\'t going to be a typical documentation project. Real-time streaming technology is inherently difficult to explain in static text, and developers needed to understand both the technical implementation and the practical troubleshooting aspects.","source":"@site/docs/ably/sse-documentation.md","sourceDirName":"ably","slug":"/ably/sse-documentation","permalink":"/portfolio/docs/ably/sse-documentation","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1},"sidebar":"tutorialSidebar","previous":{"title":"My work at Ably","permalink":"/portfolio/docs/ably/"},"next":{"title":"Webhooks security documentation","permalink":"/portfolio/docs/ably/webhooks-security"}}');var i=n(4848),a=n(8453);const r={sidebar_position:1},s="Server-sent events documentation",l={},c=[{value:"Understanding the documentation challenge",id:"understanding-the-documentation-challenge",level:2},{value:"Writing process and approach",id:"writing-process-and-approach",level:2},{value:"Connecting to developer workflows",id:"connecting-to-developer-workflows",level:2},{value:"Code examples and practical implementation",id:"code-examples-and-practical-implementation",level:2},{value:"Integration with broader real-time messaging strategy",id:"integration-with-broader-real-time-messaging-strategy",level:2},{value:"Results and developer impact",id:"results-and-developer-impact",level:2}];function d(e){const t={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"server-sent-events-documentation",children:"Server-sent events documentation"})}),"\n",(0,i.jsxs)(t.p,{children:["When I started working on the ",(0,i.jsx)(t.a,{href:"https://ably.com/docs/protocols/sse",children:"Server-Sent Events documentation"})," at Ably, I quickly realized this wasn't going to be a typical documentation project. Real-time streaming technology is inherently difficult to explain in static text, and developers needed to understand both the technical implementation and the practical troubleshooting aspects."]}),"\n",(0,i.jsx)(t.h2,{id:"understanding-the-documentation-challenge",children:"Understanding the documentation challenge"}),"\n",(0,i.jsx)(t.p,{children:"Server-Sent Events sit in a complicated space between WebSockets and simple HTTP requests. Developers often chose SSE because they thought it would be simpler than WebSockets, but then struggled with browser compatibility issues, connection management, and error handling that wasn't obvious from basic tutorials."}),"\n",(0,i.jsx)(t.p,{children:"I spent time reviewing support tickets and talking to developer advocates to understand where developers were getting stuck. The pattern was clear - people could get basic SSE working quickly, but struggled with production reliability and debugging when things went wrong."}),"\n",(0,i.jsx)(t.h2,{id:"writing-process-and-approach",children:"Writing process and approach"}),"\n",(0,i.jsx)(t.p,{children:"The biggest challenge was making real-time concepts accessible in documentation format. Unlike the repository consolidation project I later worked on at Couchbase, this required showing dynamic behavior and helping developers understand what they should expect to see."}),"\n",(0,i.jsx)(t.p,{children:"I developed a layered approach starting with simple concepts and building to production-ready implementations. Each section included working code examples, but more importantly, explanations of what developers should expect to see and how to recognize when something wasn't working correctly."}),"\n",(0,i.jsx)(t.p,{children:"The troubleshooting sections became some of the most valuable content. Drawing from the systematic diagnostic approach I had developed at Atlas Copco, I created decision trees that helped developers identify whether issues were client-side, network-related, or server configuration problems."}),"\n",(0,i.jsx)(t.h2,{id:"connecting-to-developer-workflows",children:"Connecting to developer workflows"}),"\n",(0,i.jsx)(t.p,{children:"This project reinforced lessons I had learned in my earlier work on channels and pub/sub documentation. Developers don't just want to know how SSE works technically - they need to understand when to choose SSE over WebSockets or long polling, and how SSE fits into their broader application architecture."}),"\n",(0,i.jsx)(t.p,{children:"I made sure to connect the SSE documentation to related Ably features and provided clear migration paths for developers who needed to switch protocols. This systems thinking approach, similar to what I applied to joining technologies at Atlas Copco, helped developers understand how their technical choices connected to broader implementation decisions."}),"\n",(0,i.jsx)(t.h2,{id:"code-examples-and-practical-implementation",children:"Code examples and practical implementation"}),"\n",(0,i.jsx)(t.p,{children:"Every code example in the SSE documentation was designed to be copy-pasteable and immediately functional. But unlike simple tutorial code, I included error handling, reconnection logic, and monitoring approaches that developers would need in production."}),"\n",(0,i.jsx)(t.p,{children:"The interactive elements allowed developers to test concepts immediately, similar to how I later structured the developer onboarding experience. The goal was reducing the gap between reading about SSE and actually implementing it successfully."}),"\n",(0,i.jsx)(t.h2,{id:"integration-with-broader-real-time-messaging-strategy",children:"Integration with broader real-time messaging strategy"}),"\n",(0,i.jsx)(t.p,{children:"The SSE documentation didn't exist in isolation - it was part of Ably's broader real-time messaging portfolio. I made sure developers understood when SSE was the right choice and provided clear guidance for situations where they might need to switch to WebSockets or other protocols."}),"\n",(0,i.jsx)(t.p,{children:"This connected directly to the developer journey mapping work I was doing simultaneously. Different developers had different entry points into real-time messaging, and the documentation needed to serve both developers who were new to real-time concepts and those who were comparing specific technical implementations."}),"\n",(0,i.jsx)(t.h2,{id:"results-and-developer-impact",children:"Results and developer impact"}),"\n",(0,i.jsx)(t.p,{children:"The revised SSE documentation became one of the most-referenced pages in Ably's developer resources. More importantly, it reduced support ticket volume for SSE-related issues and improved successful implementation rates for developers choosing this protocol."}),"\n",(0,i.jsx)(t.p,{children:"The systematic approach to troubleshooting and the focus on production-ready code examples influenced how I approached other protocol documentation at Ably. The principles I developed here - layered complexity, practical examples, and systematic troubleshooting - became central to all my subsequent technical writing projects."})]})}function p(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>s});var o=n(6540);const i={},a=o.createContext(i);function r(e){const t=o.useContext(a);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),o.createElement(a.Provider,{value:t},e.children)}}}]);